from collections import defaultdict

rows = [('Asha', 'Pune', 82), ('Ravi', 'Delhi', 74), ('Meera', 'pune', 91)]
by_city = defaultdict(list)
for name, city, score in rows:
    by_city[city.strip().title()].append(score)

averages = {city: sum(s) / len(s) for city, s in by_city.items()}
print(averages)  # {'Pune': 86.5, 'Delhi': 74.0}

