import csv
import sys

reader = csv.DictReader(sys.stdin)
groups = {}
skipped = 0
best = None
for row in reader:
    name = (row.get('name') or '').strip()
    city = (row.get('city') or '').strip().title()
    try:
        score = float(row.get('score') or '')
    except ValueError:
        skipped += 1
        continue
    if not name or not city:
        skipped += 1
        continue
    groups.setdefault(city, []).append((name, score))
    if best is None or (-score, name) < (-best[1], best[0]):
        best = (name, score)

for city in sorted(groups):
    people = groups[city]
    avg = sum(s for _, s in people) / len(people)
    top = min(people, key=lambda p: (-p[1], p[0]))[0]
    print(f'{city}: count={len(people)} avg={avg:.2f} top={top}')
if best:
    print(f'Overall top: {best[0]} ({best[1]:g})')
else:
    print('No valid rows')
print(f'Skipped: {skipped}')
